#!/usr/bin/env node
/**
 * editor-config.json → app/assets/js/editor-config.js
 *
 *   node scripts/editor-config.mjs --check   # generated file matches the JSON
 *   node scripts/editor-config.mjs --sync    # rewrite the generated module
 *
 * The generated module pins the SHA-256 of the committed JSON plus the owner
 * whitelist. Changing the Content repository only means editing the JSON:
 * the app re-checks the hash at runtime and falls back to the built-in values
 * when the whitelist fails.
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { RESERVED_PATHS } from '../app/assets/js/content-rules.js';
import { ownerAllowlist, repoInfo } from './repo.mjs';
import { readPublicJwk } from './config-sign.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const configPath = path.join(root, 'editor-config.json');
const outPath = path.join(root, 'app', 'assets', 'js', 'editor-config.js');

/**
 * Owners that may host the repositories. Derived from editor-config.json (plus
 * the optional `allowedOwners` pre-authorisation list) instead of a literal, so
 * an owner migration only touches that JSON.
 */
export const ALLOWED_OWNERS = ownerAllowlist();
export const FORBIDDEN_REPOS = ['core', 'alias', 'wikifactory-core', 'wikifactory-alias'];
const OWNER_RE = /^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/;
const REPO_RE = /^[A-Za-z0-9._-]{1,100}$/;

/** Hash the canonical LF form so Windows checkouts cannot change the pin. */
export function configHash(text) {
  return crypto.createHash('sha256').update(String(text).replace(/\r\n/g, '\n'), 'utf8').digest('hex');
}

/** @returns {string[]} problems (empty when the config is acceptable) */
export function validateConfig(config, { allowedOwners = ownerAllowlist(config) } = {}) {
  const problems = [];
  if (!config || typeof config !== 'object') return ['配置不是 JSON 对象'];
  if (config.version !== 1) problems.push('version 必须为 1');
  const content = config.content || {};
  if (!OWNER_RE.test(String(content.owner || ''))) problems.push('content.owner 不合法');
  else if (!allowedOwners.includes(content.owner)) {
    problems.push(`content.owner「${content.owner}」不在白名单（${allowedOwners.join(' / ')}）`);
  }
  if (!REPO_RE.test(String(content.repo || ''))) problems.push('content.repo 不合法');
  else if (FORBIDDEN_REPOS.includes(String(content.repo).toLowerCase())) {
    problems.push('Content 仓库不能是 Core / Alias');
  }
  if (content.branch !== undefined && typeof content.branch !== 'string') problems.push('content.branch 必须是字符串');
  const editor = config.editor || {};
  if (!OWNER_RE.test(String(editor.owner || ''))) problems.push('editor.owner 不合法');
  else if (!allowedOwners.includes(editor.owner)) problems.push(`editor.owner「${editor.owner}」不在白名单`);
  if (!REPO_RE.test(String(editor.repo || ''))) problems.push('editor.repo 不合法');
  if (editor.issueUrl !== undefined) {
    if (typeof editor.issueUrl !== 'string' || !/^https:\/\/github\.com\//.test(editor.issueUrl)) {
      problems.push('editor.issueUrl 必须是 https://github.com/… 链接');
    } else if (!editor.issueUrl.startsWith(`https://github.com/${editor.owner}/${editor.repo}/`)) {
      problems.push('editor.issueUrl 必须指向 editor 仓库');
    }
  }
  if (config.allowedOwners !== undefined) {
    if (!Array.isArray(config.allowedOwners) || config.allowedOwners.length === 0) {
      problems.push('allowedOwners 必须是非空数组');
    } else if (config.allowedOwners.some((owner) => !OWNER_RE.test(String(owner)))) {
      problems.push('allowedOwners 含不合法的 owner 名');
    }
  }
  const rules = config.rules;
  if (rules !== undefined) {
    if (!rules || typeof rules !== 'object') problems.push('rules 必须是对象');
    else {
      if (rules.reservedPaths !== undefined) {
        if (!Array.isArray(rules.reservedPaths)) {
          problems.push('rules.reservedPaths 必须是数组');
        } else if (
          rules.reservedPaths
            .map((item) => String(item).toLowerCase())
            .sort()
            .join('|') !==
          RESERVED_PATHS.map((item) => item.toLowerCase())
            .sort()
            .join('|')
        ) {
          problems.push('rules.reservedPaths 必须与 content-rules.js 一致（修改请走 rules:sync）');
        }
      }
      if (rules.maxUploadMb !== undefined && !(Number.isFinite(rules.maxUploadMb) && rules.maxUploadMb > 0)) {
        problems.push('rules.maxUploadMb 必须是正数');
      }
    }
  }
  for (const key of Object.keys(config)) {
    if (!['version', 'content', 'editor', 'allowedOwners', 'rules'].includes(key)) {
      problems.push(`未知字段「${key}」`);
    }
  }
  return problems;
}

export function generatedSource({ config, hash, url, owners = ownerAllowlist(config), publicJwk = readPublicJwk() }) {
  const sigUrl = url.replace(/editor-config\.json$/, 'editor-config.json.sig');
  return [
    '// Generated by scripts/editor-config.mjs --sync. Do not edit by hand.',
    `export const CONFIG_URL = '${url}';`,
    `export const CONFIG_SIG_URL = '${sigUrl}';`,
    `export const CONFIG_SHA256 = '${hash}';`,
    `export const CONFIG_PUBLIC_KEY_JWK = ${JSON.stringify(publicJwk, null, 2)};`,
    `export const ALLOWED_OWNERS = ${JSON.stringify(owners)};`,
    `export const DEFAULT_CONFIG = ${JSON.stringify(config, null, 2)};`,
    '',
  ].join('\n');
}

export function checkEditorConfig() {
  const text = fs.readFileSync(configPath, 'utf8');
  let config;
  try {
    config = JSON.parse(text);
  } catch (error) {
    return [`editor-config.json 不是合法 JSON：${error.message}`];
  }
  const problems = validateConfig(config);
  if (problems.length) return problems;
  if (!readPublicJwk()) return ['缺少 editor-config.pub.jwk（运行 npm run config:keygen）'];
  const { editorOwner, editorRepo } = repoInfo(config);
  const url = `https://raw.githubusercontent.com/${editorOwner}/${editorRepo}/main/editor-config.json`;
  const expected = generatedSource({ config, hash: configHash(text), url });
  if (!fs.existsSync(outPath)) return ['app/assets/js/editor-config.js 缺失（运行 npm run config:sync）'];
  const actual = fs.readFileSync(outPath, 'utf8').replace(/\r\n/g, '\n');
  if (actual !== expected) {
    return ['app/assets/js/editor-config.js 未同步（运行 npm run config:sync）'];
  }
  return [];
}

export function syncEditorConfig() {
  const text = fs.readFileSync(configPath, 'utf8');
  const config = JSON.parse(text);
  const { editorOwner, editorRepo } = repoInfo(config);
  const url = `https://raw.githubusercontent.com/${editorOwner}/${editorRepo}/main/editor-config.json`;
  fs.writeFileSync(outPath, generatedSource({ config, hash: configHash(text), url }));
  return ['app/assets/js/editor-config.js'];
}

function main() {
  if (process.argv.includes('--sync')) {
    const changed = syncEditorConfig();
    console.log(`[config] 已同步：${changed.join('、')}`);
  }
  const problems = checkEditorConfig();
  if (problems.length) {
    console.error('[config] 配置有问题：');
    for (const problem of problems) console.error(`  - ${problem}`);
    process.exit(1);
  }
  console.log('[config] editor-config.json 与生成模块一致。');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
